//! Exact signing-threshold fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_protocol::threshold::{RationalWeight, RationalWeightError, SigningThreshold, ThresholdError};
use serde::Deserialize;
use serde_json::Value;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    cases: Vec<ThresholdCase>,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct ThresholdCase {
    name: String,
    input_kind: String,
    input: Value,
    weighted: bool,
    size: u128,
    sith: Value,
    json: String,
    limen_hex: Option<String>,
    num: Option<u128>,
    satisfaction: Vec<SatisfactionCase>,
}

#[derive(Debug, Deserialize)]
struct SatisfactionCase {
    indices: Vec<usize>,
    result: bool,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    input_kind: String,
    input: Value,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    greater_than_one_weight: WeightQuirk,
    negative_weight: NegativeWeightQuirk,
    partial_numeric_hex: PartialHexQuirk,
    out_of_range_signature_index: IndexQuirk,
}

#[derive(Debug, Deserialize)]
struct WeightQuirk {
    input: Vec<String>,
    sith: Vec<String>,
    satisfies_zero: bool,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct NegativeWeightQuirk {
    input: Vec<String>,
    sith: Vec<String>,
    satisfies_all: bool,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct PartialHexQuirk {
    input: String,
    sith: String,
    num: u128,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct IndexQuirk {
    input: Vec<String>,
    indices: Vec<usize>,
    result: bool,
    rust_error_category: String,
}

fn fixture() -> Result<Fixture, serde_json::Error> {
    serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/threshold/v1.json"
    )))
}

#[test]
fn fixture_metadata_is_pinned() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_eq!(fixture.generated_on, "2026-08-09");
    assert_eq!(
        fixture.sources,
        ["src/keri/core/tholder.ts", "test/core/tholder.test.ts"]
    );
    Ok(())
}

#[test]
fn successful_reference_cases_match_exact_outputs() -> Result<(), Box<dyn Error>> {
    for case in fixture()?.cases {
        let threshold = construct_case(&case)?;
        assert_eq!(
            threshold.is_weighted(),
            case.weighted,
            "weighted mismatch for {}",
            case.name
        );
        assert_eq!(threshold.size(), case.size, "size mismatch for {}", case.name);
        assert_eq!(
            threshold.numeric_value(),
            case.num,
            "numeric mismatch for {}",
            case.name
        );
        assert_eq!(
            threshold.canonical_sith(),
            expected_sith(&case.sith)?,
            "sith mismatch for {}",
            case.name
        );
        assert_eq!(threshold.canonical_json(), case.json, "JSON mismatch for {}", case.name);
        assert_eq!(
            threshold.limen()?.as_deref().map(encode_hex).transpose()?,
            case.limen_hex,
            "limen mismatch for {}",
            case.name
        );
        for satisfaction in case.satisfaction {
            assert_eq!(
                threshold.is_satisfied_by(&satisfaction.indices)?,
                satisfaction.result,
                "satisfaction mismatch for {}",
                case.name
            );
        }
        assert_eq!(SigningThreshold::from_json(&case.json)?, threshold);
    }
    Ok(())
}

#[test]
fn reference_rejections_map_to_typed_failures() -> Result<(), Box<dyn Error>> {
    for case in fixture()?.rejected_cases {
        assert_eq!(case.reference_error_category, "Error");
        assert_ne!(case.reference_error_message, "");
        let category = match case.name.as_str() {
            "missing_expression" => threshold_error_category(
                &SigningThreshold::from_sith("")
                    .err()
                    .ok_or("missing threshold was accepted")?,
            ),
            "negative_numeric" => {
                assert_eq!(case.input_kind, "sith_number");
                assert_eq!(case.input, Value::from(-1));
                "Unrepresentable"
            }
            "empty_weight_list" | "mixed_clause_shape" | "clause_below_one" | "invalid_weight" | "zero_denominator" => {
                let input = serde_json::to_string(&case.input)?;
                threshold_error_category(
                    &SigningThreshold::from_json(&input)
                        .err()
                        .ok_or("reference-rejected weighted threshold was accepted")?,
                )
            }
            "numeric_limen" => {
                assert_eq!(case.input_kind, "limen");
                assert_eq!(case.input, Value::String("MAAL".to_owned()));
                assert_eq!(SigningThreshold::from_limen_qb64("MAAL")?.numeric_value(), Some(11));
                "ReferenceUnsupported"
            }
            _ => return Err(format!("unknown rejected fixture case {}", case.name).into()),
        };
        assert_eq!(
            category, case.rust_error_category,
            "category mismatch for {}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn unsafe_reference_quirks_are_strictly_diverged() -> Result<(), Box<dyn Error>> {
    let quirks = fixture()?.reference_quirks;

    let greater = quirks.greater_than_one_weight;
    assert_eq!(greater.sith, greater.input);
    assert!(greater.satisfies_zero);
    let error = RationalWeight::parse(&greater.input.join(""))
        .err()
        .ok_or("greater-than-one weight was accepted")?;
    assert_eq!(weight_error_category(&error), greater.rust_error_category);

    let negative = quirks.negative_weight;
    assert_eq!(negative.sith, negative.input);
    assert!(negative.satisfies_all);
    let error = RationalWeight::parse(negative.input.first().ok_or("negative-weight fixture was empty")?)
        .err()
        .ok_or("negative weight was accepted")?;
    assert_eq!(weight_error_category(&error), negative.rust_error_category);

    let partial = quirks.partial_numeric_hex;
    assert_eq!(partial.sith, "b");
    assert_eq!(partial.num, 11);
    let error = SigningThreshold::from_sith(&partial.input)
        .err()
        .ok_or("partial numeric hexadecimal text was accepted")?;
    assert_eq!(threshold_error_category(&error), partial.rust_error_category);

    let index = quirks.out_of_range_signature_index;
    assert!(!index.result);
    let threshold = SigningThreshold::from_json(&serde_json::to_string(&index.input)?)?;
    let error = threshold
        .is_satisfied_by(&index.indices)
        .err()
        .ok_or("out-of-range signature index was ignored")?;
    assert_eq!(threshold_error_category(&error), index.rust_error_category);
    Ok(())
}

fn construct_case(case: &ThresholdCase) -> Result<SigningThreshold, Box<dyn Error>> {
    match case.input_kind.as_str() {
        "sith_string" => Ok(SigningThreshold::from_sith(
            case.input.as_str().ok_or("sith string fixture was not a string")?,
        )?),
        "sith_number" | "thold_number" => Ok(SigningThreshold::numeric(u128::from(
            case.input.as_u64().ok_or("numeric fixture was not unsigned")?,
        ))),
        "sith_value" => Ok(SigningThreshold::from_json(&serde_json::to_string(&case.input)?)?),
        "sith_json" => Ok(SigningThreshold::from_sith(
            case.input.as_str().ok_or("sith JSON fixture was not a string")?,
        )?),
        _ => Err(format!("unknown input kind {}", case.input_kind).into()),
    }
}

fn expected_sith(value: &Value) -> Result<String, serde_json::Error> {
    match value {
        Value::String(value) => Ok(value.clone()),
        _ => serde_json::to_string(value),
    }
}

fn threshold_error_category(error: &ThresholdError) -> &'static str {
    match error {
        ThresholdError::EmptyExpression => "EmptyExpression",
        ThresholdError::EmptyThreshold => "EmptyThreshold",
        ThresholdError::InvalidExpressionShape => "InvalidExpressionShape",
        ThresholdError::ClauseBelowOne { .. } => "ClauseBelowOne",
        ThresholdError::InvalidWeight { .. } => "InvalidWeight",
        ThresholdError::IndexOutOfRange { .. } => "IndexOutOfRange",
        ThresholdError::Cesr { source } => match source.as_ref() {
            keri_cesr::CesrError::InvalidHexCharacter { .. } => "InvalidHexCharacter",
            _ => "Cesr",
        },
        _ => "Other",
    }
}

fn weight_error_category(error: &RationalWeightError) -> &'static str {
    match error {
        RationalWeightError::OutOfRange => "WeightOutOfRange",
        RationalWeightError::InvalidCharacter { .. } => "InvalidWeight",
        _ => "Other",
    }
}

fn encode_hex(bytes: &[u8]) -> Result<String, &'static str> {
    let mut encoded = String::with_capacity(bytes.len().saturating_mul(2));
    for byte in bytes {
        let high = char::from_digit(u32::from(*byte >> 4), 16).ok_or("invalid high hex nibble")?;
        let low = char::from_digit(u32::from(*byte & 0x0f), 16).ok_or("invalid low hex nibble")?;
        encoded.push(high);
        encoded.push(low);
    }
    Ok(encoded)
}
